import{_ as i,o as a,c as n,a9 as t}from"./chunks/framework.asyjyako.js";const g=JSON.parse('{"title":"Configure an advisor and manage optional models","description":"","frontmatter":{},"headers":[],"relativePath":"advisor-ui.md","filePath":"advisor-ui.md","lastUpdated":null}'),s={name:"advisor-ui.md"};function o(r,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="Configure-an-advisor-and-manage-optional-models" tabindex="-1">Configure an advisor and manage optional models <a class="header-anchor" href="#Configure-an-advisor-and-manage-optional-models" aria-label="Permalink to &quot;Configure an advisor and manage optional models {#Configure-an-advisor-and-manage-optional-models}&quot;">​</a></h1><p>The deterministic advisor requires no model. The optional advisor panel lets you choose Ollama, a local or remote Chat Completions endpoint, or one MCP HTTP advice tool. It opens without contacting the provider or downloading weights.</p><h2 id="VS-Code" tabindex="-1">VS Code <a class="header-anchor" href="#VS-Code" aria-label="Permalink to &quot;VS Code {#VS-Code}&quot;">​</a></h2><p>Run <strong>PerfChecker: Configure advisor and manage models</strong>, use the settings icon in <strong>Scenarios &amp; advice</strong>, or choose <strong>Model settings</strong> in an investigation.</p><ol><li><p>Select a provider and enter its endpoint. Remote connections require an explicit HTTPS opt-in. Enter only the <em>name</em> of a credential environment variable; never paste a token into the panel.</p></li><li><p>Choose <strong>Test connection / discover</strong>. This reads the available models or MCP tools, without sending project evidence or generating advice.</p></li><li><p>Choose <strong>Use</strong> beside a model/tool. For MCP, check the prompt argument and any other required arguments shown in its schema. The selection remains explicit; a tool name is not a guarantee that the server contains an assistant.</p></li><li><p>Customize the instructions and save. The panel updates the configured advisor file, or creates <code>perf/advisor.json</code>, then selects it in workspace settings. Existing custom provider fields are retained through the common validator.</p></li><li><p>Diagnose a scenario and choose <strong>Explain with configured model</strong>. The displayed saved evidence is used directly; otherwise the extension offers its history.</p></li></ol><p>Choose <strong>Rule-based advice only</strong> and save to disable optional advice. This does not remove model files. Choosing experiments is separately enabled and bounded by count and duration. MCP requires structured responses for this mode; free text is displayed as unverified advice and never executed.</p><h2 id="Explain-and-retain-saved-evidence" tabindex="-1">Explain and retain saved evidence <a class="header-anchor" href="#Explain-and-retain-saved-evidence" aria-label="Permalink to &quot;Explain and retain saved evidence {#Explain-and-retain-saved-evidence}&quot;">​</a></h2><ol><li><p>In <strong>Investigations</strong>, open the measurement or diagnosis you want to discuss, then select its deterministic advice. If another report is displayed, select the intended entry from <strong>Saved evidence</strong> before asking for an explanation.</p></li><li><p>Choose <strong>Explain with configured model</strong>. PerfChecker sends bounded saved evidence and its identifiers to the selected provider. The target workload is not rerun by this action.</p></li><li><p>Read the returned explanation alongside its referenced evidence and the deterministic fallback. References identify the supplied evidence; generated prose remains unverified and does not establish a performance improvement.</p></li><li><p>Under <strong>Saved evidence</strong>, use <strong>JSON</strong> or <strong>Markdown</strong> to retain the report. Use <strong>Cancel</strong> during an active request to interrupt the local worker; inspect the final status before starting another action.</p></li></ol><p>For a question and follow-up exchange, use <a href="/PerfChecker/dev/mcp-advisor#Talk-to-the-advisor">Advisor chat</a>. An explanation of one saved report and a conversation are separate actions.</p><p>The targeted native qualification exercised explanation, evidence identifiers, JSON/Markdown exports and active-request cancellation on Linux VS Code 1.141.0 with Julia 1.13.1, VSIX candidate <code>75f84f631ba3</code> and Core candidate <code>975d9351250a</code>. It used a controlled HTTP provider, so it validates the interface and transport contract rather than the reasoning quality of an authenticated model.</p><h2 id="Optional-local-model-files" tabindex="-1">Optional local model files <a class="header-anchor" href="#Optional-local-model-files" aria-label="Permalink to &quot;Optional local model files {#Optional-local-model-files}&quot;">​</a></h2><p>Install/start Ollama through its <a href="https://docs.ollama.com/quickstart" target="_blank" rel="noreferrer">official guide</a>. The panel connects to that existing service; it does not install system software. With a <strong>local Ollama</strong> endpoint selected, the panel provides:</p><ul><li><p>Model inventory with sizes reported by the server.</p></li><li><p>Explicit download of an exact model name, with a confirmation step.</p></li><li><p>Unloading from memory while retaining the files.</p></li><li><p>Deletion from the shared server after confirmation.</p></li><li><p>Cancellation and a configurable deadline, including worker startup.</p></li></ul><p>Size before download and free disk space can be unknown. Reported installed sizes include shared layers and must not be summed as unique disk usage. Cancellation stops the local worker; the server may retain partial downloads. Refresh its inventory before deciding whether another operation is needed. Deleting a model affects every project using that Ollama installation. Management is disabled for remote servers and other providers. <a id="Web-studio-and-Pluto"></a></p><h2 id="Web-interface-Oxygen-and-Pluto" tabindex="-1">Web interface (Oxygen) and Pluto <a class="header-anchor" href="#Web-interface-Oxygen-and-Pluto" aria-label="Permalink to &quot;Web interface (Oxygen) and Pluto {#Web-interface-Oxygen-and-Pluto}&quot;">​</a></h2><p>The web interface links to the <strong>same panel</strong>. Saving applies to that studio and persists under its reports directory in <code>advisor-settings.json</code>. Investigation and model-management jobs cannot run concurrently in that studio. Requests use the studio session token and are restricted to the existing loopback service.</p><p>Generated Pluto notebooks have an <strong>Optional advisor setup</strong> section with provider, prompt, MCP fields, discovery, save and model lifecycle controls. Only the action button launches a request; changing fields never does. The confirmation checkbox is required for model mutations and overwriting an existing configuration. Refresh displays the returned models/tool schemas; copy the selected identifier into the configuration before saving. The advisor file is then used by the existing narration/investigation controls.</p><p>The REPL and CLI consume the same backend, for example:</p><p>After saving <code>perf/advisor.json</code> through the panel, the equivalent Julia calls are:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_advisor_config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/advisor.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> advisor_setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(config) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inventory only; no generation/evidence</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">job </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> launch_advisor_setup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(config; action</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">:models</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">investigation_status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(job)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cancel!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(job)</span></span></code></pre></div><p>The <code>advisor-setup</code> CLI takes <code>--source=request.json</code> containing <code>config</code>, <code>action</code>, optional <code>model</code>, and <code>confirmed</code> for mutations. Its JSON output has explicit availability, <code>evidence_sent=false</code>, and <code>generation_tested=false</code>. The connection check cannot establish model quality, and some otherwise compatible model endpoints do not expose a model-list route.</p><p>See <a href="./mcp-advisor">MCP advice</a> for protocol limits and <a href="./advisors">advisors</a> for deterministic fallback and evidence verification.</p>`,22)])])}const u=i(s,[["render",o]]);export{g as __pageData,u as default};
